{
  "quality": "correct",
  "relevance": 5,
  "claims": [
    {
      "text": "LAPA is an unsupervised pretraining method for Vision-Language-Action models that does not require ground-truth robot action labels.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "We introduce Latent Action Pretraining for general Action models (LAPA), an unsupervised method for pretraining Vision-Language-Action (VLA) models without ground-truth robot action labels."
    },
    {
      "text": "Existing VLA models typically require action labels collected by human teleoperators during pretraining.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "Existing Vision-Language-Action models require action labels typically collected by human teleoperators during pretraining, which significantly limits possible data sources and scale."
    },
    {
      "text": "LAPA first trains an action quantization model with a VQ-VAE-based objective to learn discrete latent actions between image frames in videos.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "We first train an action quantization model leveraging VQ-VAE-based objective to learn discrete latent actions between image frames"
    },
    {
      "text": "LAPA then pretrains a latent VLA model to predict the learned latent actions from observations and task descriptions.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "then pretrain a latent VLA model to predict these latent actions from observations and task descriptions"
    },
    {
      "text": "This latent VLA pretraining uses internet-scale videos that do not have robot action labels.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "We propose a method to learn from internet-scale videos that do not have robot action labels."
    },
    {
      "text": "LAPA finally fine-tunes the VLA on small-scale robot manipulation data to map latent actions to robot actions.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "and finally finetune the VLA on small-scale robot manipulation data to map from latent to robot actions."
    },
    {
      "text": "The connection between latent actions and robot controls is established during the final fine-tuning stage.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "finally finetune the VLA on small-scale robot manipulation data to map from latent to robot actions."
    },
    {
      "text": "LAPA significantly outperforms existing techniques that train robot manipulation policies from large-scale videos.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "Experimental results demonstrate that our method significantly outperforms existing techniques that train robot manipulation policies from large-scale videos."
    },
    {
      "text": "LAPA outperforms a state-of-the-art VLA trained with robotic action labels on real-world manipulation tasks involving language conditioning, generalization to unseen objects, and semantic generalization to unseen instructions.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "Furthermore, it outperforms the state-of-the-art VLA model trained with robotic action labels on real-world manipulation tasks that require language conditioning, generalization to unseen objects, and semantic generalization to unseen instructions."
    },
    {
      "text": "Training only on human manipulation videos shows positive transfer and suggests that web-scale data can be used for robotics foundation models.",
      "supported": true,
      "source_number": 1,
      "evidence_quote": "Training only on human manipulation videos also shows positive transfer, opening up the potential for leveraging web-scale data for robotics foundation model."
    }
  ]
}

